-- Demo user (pokazowy) z realistyczną historią 240 dni. Wygenerowane przez
-- scripts/generate-demo-user.ts (deterministycznie). Osobny od testowego usera.
-- Konto auth (b2bb90dc-4304-41c7-821a-1cb966d30cce) utworzone ręcznie w dashboardzie — tu tylko dane portfela.

-- 1. Profil (wiersz istnieje z triggera; ustawiamy walutę i datę założenia)
values ('b2bb90dc-4304-41c7-821a-1cb966d30cce', 'PLN', now() - interval '240 days')
on conflict (id) do update set preferred_currency = excluded.preferred_currency, created_at = excluded.created_at;

-- 2. Holdings (stan na dziś)
delete from public.holdings where user_id = 'b2bb90dc-4304-41c7-821a-1cb966d30cce';

-- 3. Transakcje (historia ledgera)
delete from public.transactions where user_id = 'b2bb90dc-4304-41c7-821a-1cb966d30cce';

-- 4. Dzienne cron-snapshoty (240 dni historii wartości portfela)
delete from public.portfolio_snapshots where user_id = 'b2bb90dc-4304-41c7-821a-1cb966d30cce';

-- 5. Visit-snapshot (ostatnia wizyta)
select user_id, currency, holdings_breakdown, now(), 'visit'
from public.portfolio_snapshots where user_id = 'b2bb90dc-4304-41c7-821a-1cb966d30cce' and source = 'cron'
order by captured_at desc limit 1
on conflict (user_id) where source = 'visit' do nothing;

